using System.ComponentModel;
namespace Bai4_15;
public class RevenueRow{public string TransactionId{get;set;}="";public DateTime Date{get;set;}public string Branch{get;set;}="";public decimal Amount{get;set;}}
public class Form1:Form
{
 DateTimePicker from=new(),to=new();ComboBox branch=new();Button run=new(),cancel=new();ProgressBar bar=new();Label status=new();DataGridView grid=new();CancellationTokenSource cts;
 public Form1(){Text="Bài 4.15 - Revenue Analytics";Width=1000;Height=650;MinimumSize=new Size(750,500);var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(10),ColumnCount=1,RowCount=3};root.RowStyles.Add(new RowStyle(SizeType.AutoSize));root.RowStyles.Add(new RowStyle(SizeType.AutoSize));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));Controls.Add(root);
 var criteria=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true,WrapContents=true};from.Format=to.Format=DateTimePickerFormat.Short;from.Value=DateTime.Today.AddDays(-30);branch.DropDownStyle=ComboBoxStyle.DropDownList;branch.Items.AddRange(new object[]{"Tất cả chi nhánh","Hà Nội","Đà Nẵng","TP. Hồ Chí Minh"});branch.SelectedIndex=0;run.Text="Thống Kê Doanh Thu";run.AutoSize=true;cancel.Text="Hủy Thao Tác";cancel.AutoSize=true;cancel.Enabled=false;criteria.Controls.AddRange(new Control[]{new Label{Text="Từ ngày",AutoSize=true},from,new Label{Text="Đến ngày",AutoSize=true},to,new Label{Text="Chi nhánh",AutoSize=true},branch,run,cancel});root.Controls.Add(criteria,0,0);
 var panel=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=1};bar.Dock=DockStyle.Top;bar.Maximum=100;status.Text="Sẵn sàng.";status.AutoSize=true;panel.Controls.Add(bar);panel.Controls.Add(status);root.Controls.Add(panel,0,1);
 grid.Dock=DockStyle.Fill;grid.AutoGenerateColumns=false;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="Mã giao dịch",DataPropertyName="TransactionId",Width=150});grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="Ngày",DataPropertyName="Date",Width=150,DefaultCellStyle=new DataGridViewCellStyle{Format="dd/MM/yyyy HH:mm"}});grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="Chi nhánh",DataPropertyName="Branch",Width=180});grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="Doanh thu",DataPropertyName="Amount",Width=150,DefaultCellStyle=new DataGridViewCellStyle{Format="N0"}});root.Controls.Add(grid,0,2);run.Click+=async(_,_)=>await RunAsync();cancel.Click+=(_,_)=>cts?.Cancel();FormClosing+=(_,_)=>cts?.Cancel();}
 async Task RunAsync(){if(to.Value.Date<from.Value.Date){MessageBox.Show("Đến ngày không được trước Từ ngày.");return;}cts?.Dispose();cts=new();var token=cts.Token;run.Enabled=false;cancel.Enabled=true;bar.Value=0;status.Text="Đang tổng hợp...";string selectedBranch=branch.Text;DateTime start=from.Value.Date,end=to.Value.Date;var progress=new Progress<int>(x=>{bar.Value=Math.Clamp(x,0,100);status.Text=$"Đang xử lý... {x}%";});try{var rows=await Task.Run(async()=>{var list=new List<RevenueRow>();var random=new Random();for(int i=1;i<=60;i++){token.ThrowIfCancellationRequested();await Task.Delay(80,token);if(i%3==0){var date=start.AddDays(random.Next((end-start).Days+1)).AddHours(random.Next(8,22));var b=selectedBranch=="Tất cả chi nhánh"?new[]{"Hà Nội","Đà Nẵng","TP. Hồ Chí Minh"}[random.Next(3)]:selectedBranch;list.Add(new(){TransactionId=$"GD{i:0000}",Date=date,Branch=b,Amount=random.Next(100000,5000000)});}((IProgress<int>)progress).Report(i*100/60);}return list.Where(x=>x.Date.Date>=start&&x.Date.Date<=end&&(selectedBranch=="Tất cả chi nhánh"||x.Branch==selectedBranch)).ToList();},token);grid.DataSource=new BindingList<RevenueRow>(rows);bar.Value=100;status.Text=$"Hoàn tất: {rows.Count} giao dịch.";}catch(OperationCanceledException){bar.Value=0;status.Text="Đã hủy thao tác!";}catch(Exception ex){MessageBox.Show(ex.Message);}finally{run.Enabled=true;cancel.Enabled=false;}}
}
